//! Validation for URLs that come from untrusted search results.

use crate::error::{AppError, AppResult};

const MAX_URL_LEN: usize = 4096;
/// Demo thumbnails are small inline SVGs generated by the mock provider.
const MAX_DATA_URI_LEN: usize = 20_000;

/// Accepts absolute http(s) URLs with a host.
pub fn require_http_url(value: &str) -> AppResult<url::Url> {
    if value.len() > MAX_URL_LEN {
        return Err(AppError::Invalid("URL is too long".into()));
    }
    let parsed = url::Url::parse(value).map_err(|_| AppError::Invalid("Invalid URL".into()))?;
    match parsed.scheme() {
        "http" | "https" if parsed.host_str().is_some_and(|h| !h.is_empty()) => Ok(parsed),
        _ => Err(AppError::Invalid("Only http(s) links are allowed".into())),
    }
}

/// Accepts only https URLs (used for anything sent to a remote AI provider).
pub fn require_https_url(value: &str) -> AppResult<url::Url> {
    let parsed = require_http_url(value)?;
    if parsed.scheme() != "https" {
        return Err(AppError::Invalid(
            "Only https image URLs can be sent for analysis".into(),
        ));
    }
    Ok(parsed)
}

/// Thumbnails may be http(s) URLs or inline SVG demo images.
pub fn require_image_src(value: &str) -> AppResult<()> {
    if value.starts_with("data:image/svg+xml") {
        if value.len() > MAX_DATA_URI_LEN {
            return Err(AppError::Invalid("Inline thumbnail is too large".into()));
        }
        return Ok(());
    }
    require_http_url(value).map(|_| ())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_http_and_https() {
        assert!(require_http_url("https://example.com/a?b=1").is_ok());
        assert!(require_http_url("http://example.com").is_ok());
    }

    #[test]
    fn rejects_dangerous_schemes() {
        for bad in [
            "javascript:alert(1)",
            "file:///C:/Windows",
            "data:text/html,hi",
            "ftp://x.org",
            "not a url",
            "",
        ] {
            assert!(require_http_url(bad).is_err(), "{bad} should be rejected");
        }
    }

    #[test]
    fn https_only_for_remote_analysis() {
        assert!(require_https_url("http://example.com/img.jpg").is_err());
        assert!(require_https_url("https://example.com/img.jpg").is_ok());
    }

    #[test]
    fn image_src_allows_inline_svg_only() {
        assert!(require_image_src("data:image/svg+xml;utf8,<svg/>").is_ok());
        assert!(require_image_src("data:image/png;base64,AAAA").is_err());
        assert!(require_image_src("https://example.com/t.jpg").is_ok());
    }
}
